/**
 * Plurals Dictionary for Microsoft Dataverse & Dynamics 365 Entities
 * Maps singular logical names to Web API plural collection names and vice versa,
 * with standard fallback pluralization rules.
 */

var plurals = {
    account: "accounts",
    contact: "contacts",
    lead: "leads",
    opportunity: "opportunities",
    incident: "incidents",
    systemuser: "systemusers",
    team: "teams",
    businessunit: "businessunits",
    task: "tasks",
    email: "emails",
    phonecall: "phonecalls",
    appointment: "appointments",
    letter: "letters",
    fax: "faxes",
    activitypointer: "activitypointers",
    activitymimeattachment: "activitymimeattachments",
    annotation: "annotations",
    queue: "queues",
    queueitem: "queueitems",
    competitor: "competitors",
    invoice: "invoices",
    invoicedetail: "invoicedetails",
    quote: "quotes",
    quotedetail: "quotedetails",
    salesorder: "salesorders",
    salesorderdetail: "salesorderdetails",
    product: "products",
    productpricelevel: "productpricelevels",
    pricelevel: "pricelevels",
    uom: "uoms",
    uomschedule: "uomschedules",
    discount: "discounts",
    discounttype: "discounttypes",
    campaign: "campaigns",
    campaignactivity: "campaignactivities",
    campaignresponse: "campaignresponses",
    list: "lists",
    entitlement: "entitlements",
    entitlementtemplate: "entitlementtemplates",
    contract: "contracts",
    contractdetail: "contractdetails",
    contracttemplate: "contracttemplates",
    kbarticle: "kbarticles",
    knowledgearticle: "knowledgearticles",
    sla: "slakpis",
    slakpiinstance: "slakpiinstances",
    workflow: "workflows",
    asyncoperation: "asyncoperations",
    pluginassembly: "pluginassemblies",
    plugintype: "plugintypes",
    plugintracelog: "plugintracelogs",
    sdkmessage: "sdkmessages",
    sdkmessagefilter: "sdkmessagefilters",
    sdkmessageprocessingstep: "sdkmessageprocessingsteps",
    sdkmessageprocessingstepimage: "sdkmessageprocessingstepimages",
    solution: "solutions",
    publisher: "publishers",
    role: "roles",
    systemuserroles: "systemuserrolescollection",
    teamroles: "teamrolescollection",
    fieldsecurityprofile: "fieldsecurityprofiles",
    territory: "territories",
    transactioncurrency: "transactioncurrencies",
    connection: "connections",
    connectionrole: "connectionroles",
    bulkoperation: "bulkoperations",
    importfile: "importfiles",
    importjob: "importjobs",
    syncerror: "syncerrors"
};

// Inverted lookup map
var singulars = {};
for (var key in plurals) {
    if (plurals.hasOwnProperty(key)) {
        singulars[plurals[key]] = key;
    }
}

/**
 * Resolves an entity logical name to its Web API plural name.
 */
function getPluralName(singular) {
    if (!singular) return '';
    var lower = singular.toLowerCase().trim();
    if (plurals[lower]) return plurals[lower];

    // Standard Dataverse pluralization rules
    if (lower.endsWith('y') && !lower.endsWith('ay') && !lower.endsWith('ey') && !lower.endsWith('oy') && !lower.endsWith('uy')) {
        return lower.slice(0, -1) + 'ies';
    }
    if (lower.endsWith('s') || lower.endsWith('x') || lower.endsWith('z') || lower.endsWith('ch') || lower.endsWith('sh')) {
        return lower + 'es';
    }
    return lower + 's';
}

/**
 * Resolves an entity plural collection name to its singular logical name.
 */
function getSingularName(plural) {
    if (!plural) return '';
    var lower = plural.toLowerCase().trim();
    if (singulars[lower]) return singulars[lower];

    if (lower.endsWith('ies')) {
        return lower.slice(0, -3) + 'y';
    }
    if (lower.endsWith('es') && (lower.endsWith('shes') || lower.endsWith('ches') || lower.endsWith('xes') || lower.endsWith('sses'))) {
        return lower.slice(0, -2);
    }
    if (lower.endsWith('s')) {
        return lower.slice(0, -1);
    }
    return lower;
}
